{
  "verdict": "request_changes",
  "summary": "Fails to return an empty list when limit is 0, violating the explicit contract requirement.",
  "findings": [
    {
      "finding_id": "zero_limit_returns_full_list",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "When limit is 0, the expression items[-limit:] evaluates to items[-0:]. In Python, negative zero in slice indexing is treated as positive zero, making it equivalent to items[0:], which returns the entire input list instead of an empty list.",
      "evidence": "SPEC.md explicitly states: 'limit is a non-negative integer. Zero returns an empty list.' For the triggering input recent([1, 2, 3], 0), the candidate returns [1, 2, 3] rather than [], directly violating the contract."
    }
  ]
}
